const body = $input.first().json.body || $input.first().json || {};
const text = String(body.message?.text || body.query || '').trim();
const chatId = String(body.message?.chat?.id || body.chat_id || '');
const prToken = $env.TELEGRAM_PR_BOT_TOKEN || '';
const groqKey = $env.GROQ_API_KEY || '';
const BRAND = $env.BRAND_NAME || "Tradesejon";
const MENTORS = $env.MENTORS_LIST || "Lead Strategist, Mentor Alpha, Mentor Beta, Mentor Gamma, Mentor Delta";
const PLATFORMS = $env.SUPPORTED_PLATFORMS || "Webull, Interactive Brokers (IBKR), TradingView";
const SCHEDULE = $env.LIVE_SESSION_SCHEDULE || "Mon-Fri 9:30 PM Local Time";
const VIP_USD = $env.VIP_MONTHLY_USD || "45";
const PRIVATE_USD = $env.PRIVATE_SESSION_USD || "100";

async function sendPrReply(msg) {
  if (chatId && prToken) {
    await fetch(`https://api.telegram.org/bot${prToken}/sendMessage`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: chatId, text: msg, parse_mode: 'HTML' })
    }).catch(() => null);
  }
}

if (/(?:indicator|script|scanner|سكانر|مؤشر|توصية)/i.test(text)) {
  const guardMsg = `🔒 <b>${BRAND} PR Desk:</b>\nVIP Indicators and Scanners are available to active members.\nSubscribe via Whop ($${VIP_USD}/mo): ${$env.WHOP_CHECKOUT_URL || 'Configure WHOP_CHECKOUT_URL'}`;
  await sendPrReply(guardMsg);
  return [{ json: { ok: true, guarded: true, reply: guardMsg } }];
}

if (/(?:meen.*mentors?|el\s*mentors?|المنتورز|المدربين|المحاضرين|الموجهين)/i.test(text)) {
  const mMsg = `👨‍🏫 <b>${BRAND} Certified Mentors:</b>\n${MENTORS}\n\n• <b>Live Schedule:</b> ${SCHEDULE}\n• <b>Private 1-on-1 Session (4h):</b> $${PRIVATE_USD}`;
  await sendPrReply(mMsg);
  return [{ json: { ok: true, faq_matched: true, reply: mMsg } }];
}

if (/(?:eh\s*nzamk|nzamk|nezamk|bt3mlo\s*eh|نظامكم|بتشتغلوا)/i.test(text)) {
  const sysMsg = `👑 <b>Welcome to ${BRAND}:</b>\n• <b>Live Discord VIP + Scanner:</b> $${VIP_USD}/month (${SCHEDULE})\n• <b>Mentors:</b> ${MENTORS}\n• <b>Platforms:</b> ${PLATFORMS}`;
  await sendPrReply(sysMsg);
  return [{ json: { ok: true, faq_matched: true, reply: sysMsg } }];
}

// Check custom uploaded Knowledge Base (Disk + MongoDB)
let customKbContext = '';
try {
  const fs = require('fs');
  const kbFile = ($env.KB_DIR || '/home/node/rag-knowledge-base') + '/custom_knowledge.json';
  if (fs.existsSync(kbFile)) {
    const parsed = JSON.parse(fs.readFileSync(kbFile, 'utf8'));
    const entries = Array.isArray(parsed) ? parsed : (parsed.entries || []);
    const qLow = text.toLowerCase();
    for (const e of entries) {
      if (e.content && (qLow.includes(String(e.title || '').toLowerCase()) || String(e.content).toLowerCase().split(/\s+/).filter(w => w.length > 3 && qLow.includes(w)).length >= 2)) {
        const hitMsg = `📚 <b>${e.title}:</b>\n\n${String(e.content).slice(0, 1200)}`;
        await sendPrReply(hitMsg);
        return [{ json: { ok: true, custom_kb_matched: true, reply: hitMsg } }];
      }
    }
    customKbContext = entries.slice(0, 5).map(e => `${e.title}: ${String(e.content || '').slice(0, 200)}`).join('\n');
  }
} catch (e) {}

let reply = `Welcome to ${BRAND} Desk! Mentors: ${MENTORS}. Discord VIP: $${VIP_USD}/mo (${SCHEDULE}).`;
if (groqKey && text) {
  const r = await fetch('https://api.groq.com/openai/v1/chat/completions', {
    method: 'POST', headers: { 'Authorization': `Bearer ${groqKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'llama-3.3-70b-versatile',
      messages: [
        { role: 'system', content: `You are ${BRAND} Official Desk synced with Discord & AIOS Knowledge Base. Mentors: ${MENTORS}. Platforms: ${PLATFORMS}. Discord VIP: $${VIP_USD}/mo. Private 1-on-1: $${PRIVATE_USD}. Schedule: ${SCHEDULE}. Never invent $29 pricing or 7-day trials. Custom Knowledge:\n${customKbContext}` },
        { role: 'user', content: text }
      ]
    })
  }).then(res => res.json()).catch(() => ({}));
  if (r.choices?.[0]?.message?.content) reply = r.choices[0].message.content;
}

await sendPrReply(reply);
return [{ json: { ok: true, reply } }];
